const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=k=>'assets/'+k+'.jpg';
const portraits=['baby','toddler','schoolchild','preteen','teen','young-adult','middle-aged','senior'];
const labels=['newborn / infant','toddler','child / schoolchild','pre-teen / tween','teenager / adolescent','young adult','middle-aged adult','senior / retiree'];
const photo=(k,alt='',cl='visual')=>`<img class="${cl}" src="${asset(k)}" alt="${esc(alt)}">`;
photos.splice(0,photos.length,...portraits.map((p,i)=>[asset(p),labels[i]]));
const extraWords=[['infant','0–1 approximately','An infant needs care day and night.','младенец','baby'],['preschooler','before school, approximately 3–5','A preschooler learns through play.','дошкольник','toddler-outdoors'],['pre-teen / tween','approximately 9–12','A tween is between childhood and the teenage years.','предподросток','preteen'],['adolescent','a young person developing into an adult','An adolescent may want more privacy.','подросток','teen'],['adult','a grown-up person','Adults can learn new skills too.','взрослый','young-adult'],['elderly person','an older person; no fixed boundary','Ask an elderly person about their interests.','пожилой человек','senior'],['pensioner','someone who receives a pension','A pensioner can still have a busy life.','пенсионер','senior'],['retiree','someone who has retired','A retiree may start a new hobby.','человек на пенсии','senior'],['centenarian','100 years old or older','A centenarian has lived for a century.','долгожитель 100+','senior']];
const translations=['младенец','малыш, начинающий ходить','ребёнок','подросток','молодой взрослый','среднего возраста','пожилой человек'];
cards.forEach((c,i)=>{c.push(translations[i],['baby','toddler','schoolchild','teen','young-adult','middle-aged','senior'][i])});cards.push(...extraWords);
let voiceName='',autoCards=null;function voices(){if(!('speechSynthesis' in window))return [];return speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en'))}
speak=function(t){if(!('speechSynthesis'in window))return; speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-GB';u.rate=.9;u.voice=voices().find(v=>v.name===voiceName)||voices().find(v=>v.lang==='en-GB')||null;speechSynthesis.speak(u)};
function voiceSelect(){return `<label class="note">Voice <select onchange="voiceName=this.value">${voices().map(v=>`<option ${v.name===voiceName?'selected':''} value="${esc(v.name)}">${esc(v.name)}</option>`).join('')}</select></label>`}
rCards=function(){const c=cards[card];stage.innerHTML=shell(`<div class="flashArea"><div class="flashWrap"><div class="cardtools"><button class="action alt" onclick="speak(cards[card][0])">Listen</button><button class="action alt" onclick="$('#flash').classList.toggle('flip')">Hint / Flip</button><button class="action alt" onclick="this.classList.toggle('chosen')">Favourite</button><button class="action alt" onclick="document.documentElement.requestFullscreen?.()">Full screen</button></div><div class="flash" id="flash" tabindex="0" role="button" aria-label="Flip vocabulary card" onclick="this.classList.toggle('flip')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}"><div class="inner"><div class="face"><div class="term">${c[0]}</div><div class="note">Say the meaning. Flip to check.</div></div><div class="face back"><div class="flashback">${photo(c[4],'Illustrative photo')}<div><h2>${c[0]}</h2><h3>${c[3]}</h3><p>${c[1]}</p><p>${c[2]}</p></div></div></div></div></div><div class="controls"><button onclick="card=(card-1+cards.length)%cards.length;rCards()">Back</button><b>${card+1} / ${cards.length}</b><button onclick="if(autoCards){clearInterval(autoCards);autoCards=null}else{autoCards=setInterval(()=>{card=(card+1)%cards.length;rCards();speak(cards[card][0])},5000)}">Play / Pause</button><button onclick="card=(card+1)%cards.length;rCards()">Next</button></div>${voiceSelect()}</div></div>`)};
// Use the supplied recording with a genuine seekable progress bar.
player=function(){return `<div class="player">${photo('family','A family together','audioPhoto')}<h3>My Family at Different Stages of Life</h3><audio controls preload="metadata" src="assets/teenage-life.mp3" aria-label="Original listening recording"></audio><p class="note">Listen, pause and drag the progress bar to replay a part.</p><button class="action alt" onclick="revealText('Audio script',script)">Teacher · transcript</button></div>`};
stopListen=function(){document.querySelectorAll('audio').forEach(a=>a.pause());clearInterval(listenTimer);if('speechSynthesis'in window)speechSynthesis.cancel()};
function revealText(title,text){$('#teacherTitle').textContent=title;$('#teacherText').textContent=text;$('#modal').classList.add('on')}
function enlarge(src){const d=document.createElement('dialog');d.className='imageDialog';d.innerHTML=`<button class="action" onclick="this.closest('dialog').close();this.closest('dialog').remove()">Close</button><img src="${src}" alt="Textbook exercise enlarged">`;document.body.append(d);d.showModal()}
rBefore=function(){stage.innerHTML=shell(`<div class="listen">${player()}<div class="panel"><h3>Look at these five people. Predict their life stages.</h3><div class="miniGallery">${['toddler','teen','young-adult','middle-aged','senior'].map(p=>photo(p,'Person to describe')).join('')}</div><div class="pool">${sh(['a toddler','a teenager','a young adult','a middle-aged adult','a senior']).map(x=>`<span class="token">${x}</span>`).join('')}</div><p>Listen for Ben, Max, Jake, Ben’s dad and Grandpa Tom.</p></div></div>`)};
let mystery=0;
rGuess=function(){stage.innerHTML=shell(`<div class="guessFull"><div class="photos">${photos.map(([src,l],i)=>`<button class="person" onclick="mystery=${i};rGuess()"><img src="${src}" alt="Person ${i+1}"><b>${i+1}</b></button>`).join('')}</div><div class="panel"><b>Person ${mystery+1}</b><p>What stage of life is this person at? Approximately how old are they? What matters to them? What problems might they face?</p><button class="action" onclick="revealText('Possible description',labels[mystery]+'. Ages are estimated from appearance; other well-reasoned answers are welcome.')">Reveal suggestion</button></div></div>`)};
const extra=[];function ext(title,topic,render,note){const i=names.length;names.push(title);subs.push('');tnotes.push(note||'Extension: ask for a reason or example. Accept justified alternatives.');renderers.push(render);extra.push({i,topic});return i}
let matchP=0,matchChoices={};
ext('Photo → stage → age → activity','life',()=>{stage.innerHTML=shell(`<div class="grid2"><div class="panel">${photo(portraits[matchP],'Mystery person')}<div class="controls"><button onclick="matchP=(matchP+7)%8;render()">Back</button><b>Person ${matchP+1} / 8</b><button onclick="matchP=(matchP+1)%8;render()">Next</button></div></div><div class="panel"><h3>Build your own match</h3><p>The photos, ages, stages and activities are separate. Some activities fit several ages.</p>${['Stage','Age','Possible activity'].map((l,i)=>`<label class="field">${l}<select onchange="matchChoices[matchP+'-${i}']=this.value"><option>Choose</option>${sh([labels,['0–1','2–3','4–8','9–12','13–19','20–39','40–64','65+'],['learn to walk','start school','play with friends','choose school subjects','study or start work','change careers','spend time with grandchildren','learn a new skill']][i]).map(x=>`<option ${matchChoices[matchP+'-'+i]===x?'selected':''}>${x}</option>`).join('')}</select></label>`).join('')}<button class="action" onclick="revealText('Possible match',labels[matchP]+'. Age ranges are approximate. Explain why your activity fits.')">Check & explain</button></div></div>`)});
ext('Sorting · overlapping words','life',()=>{let terms=['infant','toddler','preschooler','schoolchild','tween','teenager','adolescent','young adult','adult','middle-aged person','senior citizen','pensioner','retiree'];stage.innerHTML=shell(`<div class="panel"><h3>Build a life-stage sequence. Which words overlap?</h3><div class="pool">${sh(terms).map(t=>`<button class="token" onclick="$('#builtExtra').append(this)">${t}</button>`).join('')}</div><div id="builtExtra" class="pool dropzone"></div><button class="action" onclick="revealText('Suggested sequence','infant → toddler → preschooler → schoolchild → tween → teenager/adolescent → young adult → middle-aged person → senior citizen. Adult is a broad category. Pensioner describes a pension recipient; retiree describes someone who has retired. These are not exact age bands.')">Check</button><button class="action alt" onclick="render()">Reset</button></div>`)});
const whoQuotes=['“I’m not tired!”','“Everyone in my class has one.”','“I have no idea what I want to do with my life.”','“I wish I had more free time.”','“When I was your age…”','“I finally have time to travel.”'];
let deckPos={};function discussion(title,topic,items,pics,help,note){let ix;ix=ext(title,topic,()=>{const p=deckPos[ix]||0;stage.innerHTML=shell(`<div class="grid2"><div class="panel">${photo(pics[p%pics.length],'Situation illustration')}<div class="controls"><button onclick="deckPos[${ix}]=(${p}+${items.length}-1)%${items.length};render()">Back</button><b>${p+1} / ${items.length}</b><button onclick="deckPos[${ix}]=(${p}+1)%${items.length};render()">Next</button></div></div><div class="panel discussion"><h2>${items[p]}</h2><p>${help}</p><textarea aria-label="Your ideas" placeholder="Your ideas / examples"></textarea><div class="controls"><button class="action" onclick="speak(${JSON.stringify(items[p]).replaceAll('"','&quot;')})">Listen</button><button class="action alt" onclick="timer30(this,40)">Start 40s</button><button class="action alt" onclick="complete()">Discussed</button></div></div></div>`)} ,note);return ix}
function timer30(b,n){clearInterval(window.shortTimer);b.textContent=n+'s';window.shortTimer=setInterval(()=>{n--;b.textContent=n>0?n+'s':'Time';if(n<=0)clearInterval(window.shortTimer)},1000)}
discussion('Who Would Say It?','life',whoQuotes,['toddler','schoolchild','teen','middle-aged','senior','senior'],'Choose: toddler / child / teenager / young adult / parent / retiree. Could someone else say it?');
const problems=['making friends at a new school','choosing a career','balancing work and family','becoming financially independent','dealing with retirement','feeling pressure from parents','worrying about health','wanting more freedom'];
discussion('Life Stage Problems','life',problems,['schoolchild','teen','middle-aged','young-adult','senior'],'Match to A (7), B (16), C (25), D (42), E (70). More than one person can have the same problem. Explain.');
let timelineOrder=[];const emmaEvents=['move to London','start university','meet her husband','become a teacher','have twins','move abroad','change career','run her first marathon','retire'];
ext('Emma · Life Timeline Challenge','life',()=>{stage.innerHTML=shell(`<div class="panel"><h3>Emma, 68 · a fictional life</h3><p>Guess the order and an approximate age for every event. Click the events in your chosen order.</p><div class="pool">${sh(emmaEvents.filter(x=>!timelineOrder.includes(x))).map((x)=>`<button class="token" onclick="timelineOrder.push(this.textContent);render()">${x}</button>`).join('')}</div><ol>${timelineOrder.map(x=>`<li>${x} <input type="number" min="0" max="68" aria-label="Age at ${x}" placeholder="age"></li>`).join('')}</ol><button class="action" onclick="revealText('Emma: fictional story reveal','18: moved to London and started university. 21: met her future husband. 23: became a teacher. 30: had twins. 39: moved abroad. 45: changed career. 60: ran her first marathon. 66: retired. 68: today. This timeline was invented for the lesson, not a real biography.')">Reveal story</button><button class="action alt" onclick="timelineOrder=[];render()">Reset</button></div>`)});
ext('One Person Through Life','life',()=>{stage.innerHTML=shell(`<div class="panel"><img class="lifeStrip" src="assets/one-person.jpg" alt="One imagined male at five ages"><div class="five">${[8,16,25,45,70].map(a=>`<div><h2>${a}</h2><textarea aria-label="Life at ${a}" placeholder="At ${a}, he might…"></textarea></div>`).join('')}</div><p>At 8 he probably… · At 16 he might… · By 25 he may have… · When he is 45…</p><p class="note">Imagined portraits of one fictional person. Describe his past, present and possible future.</p></div>`)});
const bestAreas=['freedom','friendship','travelling','learning','earning money','creativity','happiness','taking risks','starting again'];
ext('Which Age Is Best?','life',()=>{stage.innerHTML=shell(`<div class="panel"><h3>5 · 15 · 25 · 40 · 65 · 85</h3><p>Choose SIX of the nine categories. Use each age once. Explain which three categories you left out.</p><div class="three">${bestAreas.map(x=>`<label class="field">${x}<select onchange="uniqueAges(this)"><option value="">Skip</option>${[5,15,25,40,65,85].map(n=>`<option>${n}</option>`).join('')}</select></label>`).join('')}</div><div id="ageFeedback"></div><button class="action" onclick="complete()">Explain choices</button></div>`)} ,'Original source listed nine categories but only six ages with no repeats. Preserve all categories and select six per round; use remaining categories in a second round.');
function uniqueAges(el){const vals=[...stage.querySelectorAll('select')].map(x=>x.value).filter(Boolean);if(new Set(vals).size!==vals.length){el.value='';$('#ageFeedback').textContent='That age is already used. Choose another or swap.'}else $('#ageFeedback').textContent=vals.length+' / 6 ages chosen'}
