discussion('Share / Keep Private / Ask First','reading',['first day at school','embarrassing baby photo','family holiday','child’s exam results','funny video of your toddler','teenager’s birthday party','child’s medical problem'],['preteen','book-baby','family','teen','book-toddler','teen','book-selfie'],'Choose SHARE IT / KEEP IT PRIVATE / ASK FIRST. Who should decide? What would you ask before posting?');
discussion('Sharenting · FOR / AGAINST','reading',['Would you post photos of your children online?','At what age should children have a say in what parents post about them?','Is sharenting good or bad?'],['book-selfie','book-toddler','family'],'Give one argument FOR, one AGAINST, a concrete example and your conclusion.');
discussion('Use It or Lose It','life',['Being independent means…','One challenge teenagers face is…','To manage money, you need to…','When people retire, they can…','My current stage of life is…','A toddler usually…'],['young-adult','teen','graduation','senior','preteen','toddler'],'Finish the sentence, explain and give an example in 30 seconds.');
// Every textbook task is separately reachable and has a checked teacher key.
let bookOffset={},bookInputs={};
function bookRender(b,k){let start=bookOffset[k]||0;const prompts=b.answers.length?b.prompts.slice(start,start+5):b.prompts;stage.innerHTML=shell(`<div class="bookLayout"><div class="sourcePanel"><img src="${b.img}" alt="Gateway to the World B1 page ${b.page}: ${esc(b.title)}" onclick="enlarge(this.src)"><button class="action alt" onclick="enlarge('${b.img}')">Enlarge source</button></div><div class="panel bookAnswer"><p class="note">Gateway to the World B1 · p${b.page} · ${b.title}</p>${prompts.map((p,j)=>`<label class="field">${p}${b.answers.length?`<input value="${esc(bookInputs[k+'-'+(start+j)]||'')}" oninput="bookInputs['${k}-${start+j}']=this.value" aria-label="Answer ${esc(p)}">`:`<textarea aria-label="${esc(p)}"></textarea>`}</label>`).join('')}<div class="controls">${b.answers.length>5?`<button onclick="bookOffset[${k}]=Math.max(0,${start}-5);render()">Back</button><b>${start+1}–${Math.min(start+5,b.answers.length)} / ${b.answers.length}</b><button onclick="bookOffset[${k}]=${start+5}<${b.answers.length}?${start+5}:0;render()">Next</button>`:''}</div><button class="action" onclick="checkBook(${k})">${b.answers.length?'Check / model answers':'Teacher guidance'}</button><div id="bookFeedback" class="feedback"></div></div></div>`)}
function norm(s){return s.toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim()}
function checkBook(k){let b=bookTasks[k],start=bookOffset[k]||0;if(!b.answers.length){revealText('Teacher guidance',b.note);return}let rows=b.answers.slice(start,start+5).map((a,j)=>{const entered=bookInputs[k+'-'+(start+j)]||'';const ok=a.split('|').some(v=>norm(v)===norm(entered));return `${b.prompts[start+j]}: ${ok?'Correct':'Model: '+a.split('|')[0]}`});$('#bookFeedback').textContent=rows.join('\n')}
bookTasks.forEach((b,k)=>ext(b.title,b.topic,()=>bookRender(b,k),b.note+(b.answers.length?'\n\nKEY\n'+b.answers.map((x,i)=>b.prompts[i]+': '+x).join('\n'):'')));
// Contextual extension practice, one question at a time.
const grammarQs=[['When she was 25, she ___ abroad.',['moved','has moved','is moving'],0],['Jake ___ at university at the moment.',['studies','is studying','study'],1],['My dad ___ jobs recently.',['change','changing','changed'],2],['She ___ a marathon before.',['has never run','never ran yesterday','is never run'],0],['Look at those plans: he ___ start a business.',['going','is going to','goes'],1],['If I could go back, I ___ more risks.',['will take','would take','took'],1],['If I had studied harder, I ___ the exam.',['would have passed','will pass','would pass'],0],['I ___ what you mean.',['am understanding','understand','understands'],1]];
let gq=0;ext('Grammar through Life','life',()=>quizOne(grammarQs,gq,(j)=>{gq=j;render()},'gq'));
let cq=0;const chatQs=[['What ___ now?',['do you do','are you doing','you do'],1],['I usually ___ homework at home.',['am doing','does','do'],2],['Today I ___ in the library.',['am studying','study','studies'],0],['I ___ the answer.',['am knowing','know','knowing'],1],['Why ___?',['is the toddler crying','does the toddler crying','the toddler cries'],0],['My parents ___ it is funny.',['are thinking','thinks','think'],2]];ext('Chat Challenge','grammar',()=>quizOne(chatQs,cq,(j)=>{cq=j;render()},'cq'));
function quizOne(qs,pos,advance,key){const q=qs[pos%qs.length];window.quizAdvance=()=>advance((pos+1)%qs.length);stage.innerHTML=shell(`<div class="game"><div class="gameCard"><div class="score">${pos+1} / ${qs.length}</div><h3>${q[0]}</h3><div class="answers">${sh(q[1].map((v,i)=>({v,ok:i===q[2]}))).map(x=>`<button onclick="this.parentElement.querySelectorAll('button').forEach(b=>b.disabled=true);$('#quizfb').textContent=${x.ok}?'Correct':'Answer: '+${JSON.stringify(q[1][q[2]]).replaceAll('"','&quot;')}">${x.v}</button>`).join('')}</div><p id="quizfb"></p><button class="action" onclick="quizAdvance()">Next</button></div></div>`)}
const nounPairs=[['argue','argument'],['permit','permission'],['differ','difference'],['explain','explanation'],['confident','confidence'],['adolescent','adolescence'],['embarrass','embarrassment'],['solve','solution'],['enjoy','enjoyment'],['improve','improvement'],['independent','independence'],['connect','connection']];let nounPos=0;
ext('Build the Noun','suffixes',()=>{const p=nounPairs[nounPos];stage.innerHTML=shell(`<div class="grid2"><div class="panel">${photo('book-social','Social media and communication')}</div><div class="panel discussion"><h2>${p[0]} → ?</h2><div class="pool">${['-ment','-ion','-ence'].map(x=>`<button class="token" onclick="this.classList.toggle('chosen')">${x}</button>`).join('')}</div><input id="nounAnswer" placeholder="Build the complete noun" aria-label="Noun"><button class="action" onclick="$('#nounfb').textContent=norm($('#nounAnswer').value)===nounPairs[nounPos][1]?'Correct — now use it in a sentence.':'Answer: '+nounPairs[nounPos][1]">Check</button><p id="nounfb"></p><div class="controls"><b>${nounPos+1} / ${nounPairs.length}</b><button onclick="nounPos=(nounPos+1)%nounPairs.length;render()">Next</button></div></div></div>`)});
// Audio-only speaker identification: the quote is heard only after Play.
let saidPos=0; rSaid=function(){const q=said[saidPos];stage.innerHTML=shell(`<div class="listen">${player()}<div class="panel discussion"><h3>Who said it? ${saidPos+1} / ${said.length}</h3><p>Listen to a rephrased quote. Choose the family member.</p><button class="action" onclick="speak(said[saidPos][0])">Play quote</button><div class="answers">${['Ben','Jake','Dad','Grandpa'].map(x=>`<button onclick="$('#saidfb').textContent='${x}'===said[saidPos][1]?'Correct':'Try listening again'">${x}</button>`).join('')}</div><p id="saidfb"></p><button class="action alt" onclick="saidPos=(saidPos+1)%said.length;render()">Next</button>${voiceSelect()}</div></div>`)};
// Sprint ends once; answer events cannot restart an expired timer.
let sprintActive=false,streak=0,bestStreak=0,spErrors=[];
rSprint=function(){stage.innerHTML=shell(`<div class="game"><div class="gameCard"><h3>60-second Sprint</h3><p>Choose quickly. Build a streak.</p><button class="action" onclick="startSprint()">Start</button></div></div>`)};
function startSprint(){clearInterval(sprintInt);sprintActive=true;spi=0;sps=0;streak=0;bestStreak=0;sptime=60;spErrors=[];drawSprint();sprintInt=setInterval(()=>{sptime--;if($('#sptime'))$('#sptime').textContent=sptime;if(sptime<=0)endSprint()},1000)}
function drawSprint(){const q=sprint[spi%sprint.length];stage.innerHTML=shell(`<div class="game"><div class="gameCard"><div class="score"><span id="sptime">${sptime}</span>s · SCORE ${sps} · STREAK ${streak}</div><h3>${q[0]}</h3><div class="answers">${sh(q[1].map((x,i)=>[x,i===q[2]])).map(x=>`<button onclick="sAnswer(${x[1]})">${x[0]}</button>`).join('')}</div></div></div>`)}
sAnswer=function(ok){if(!sprintActive)return;if(ok){sps++;streak++;bestStreak=Math.max(bestStreak,streak)}else{streak=0;const q=sprint[spi%sprint.length];spErrors.push(q[0]+' → '+q[1][q[2]])}spi++;drawSprint()};
function endSprint(){sprintActive=false;clearInterval(sprintInt);sprintInt=null;complete();stage.innerHTML=shell(`<div class="game"><div class="gameCard"><h3>Score ${sps}</h3><p>Best streak: ${bestStreak}</p><p>${spErrors.length?spErrors.map(esc).join('<br>'):'No errors!'}</p><button class="action" onclick="startSprint()">Play again</button></div></div>`)}
