const bombQ=[...kah.slice(0,10).map(q=>[q[0],q[1][q[2]]]),['Name one age stereotype.','Any supported example'],['Name two responsibilities Jake has.','cook, clean, manage money']];
rBomb=function(){stage.innerHTML=shell(`<div class="bombArea"><div class="controls"><b>Team A ${bombScores[0]} · Team B ${bombScores[1]}</b><button onclick="bombTeam=1-bombTeam;rBomb()">Turn: ${bombTeam?'B':'A'}</button><button onclick="bombUsed.clear();bombScores=[0,0];rBomb()">Reset</button></div><div class="bombs">${bombQ.map((q,i)=>`<button class="bomb" ${bombUsed.has(i)?'disabled':''} onclick="bombQuestion=${i};bombOpen()">${bombUsed.has(i)?'Used':i+1}</button>`).join('')}</div></div>`)};
