function rTimeline(){stage.innerHTML=shell(`<div class="timelineTask"><p>Drag each shuffled stage to an age on the line. Or choose a card, then tap a year. You can move a card again.</p><div class="axisPool">${axisPool.filter(i=>axisPlaced[i]===undefined).map(i=>`<button draggable="true" ondragstart="axisSelected=${i};event.dataTransfer.setData('text/plain','stage:${i}')" onclick="axisSelected=${i};rTimeline()" class="${axisSelected===i?'chosen':''}">${axisStages[i][0]}</button>`).join('')}</div><div class="ageAxis" role="group" aria-label="Age line from zero to one hundred" ondragover="event.preventDefault()" ondrop="axisFromEvent(event)" onclick="axisFromEvent(event)"><div class="axisLine"></div>${Array.from({length:11},(_,i)=>`<span class="axisTick" style="left:${i*10}%">${i*10}</span>`).join('')}${Object.entries(axisPlaced).map(([id,age])=>{const i=Number(id),ok=age>=axisStages[i][1]&&age<=axisStages[i][2];return `<div class="axisMarker ${axisChecked?(ok?'correct':'retry'):''}" style="left:clamp(0px,${age}%,calc(100% - 138px));top:${85+(i%3)*66}px"><button draggable="true" ondragstart="axisSelected=${i};event.dataTransfer.setData('text/plain','stage:${i}')" onclick="event.stopPropagation();axisSelected=${i};rTimeline()">${axisStages[i][0]}<b>${age} years ${axisChecked?(ok?'✓':'↻'):''}</b></button></div>`}).join('')}</div><div class="axisControls"><label>Precise age <input id="axisAge" type="number" min="0" max="100" value="${axisSelected!==null?(axisPlaced[axisSelected]??0):0}"></label><button class="action" onclick="axisPlace(axisSelected,Number($('#axisAge').value))">Place selected card</button><button class="action" onclick="axisChecked=true;rTimeline()">Check</button><button class="action alt" onclick="axisReset()">Shuffle / reset</button><button class="action alt" onclick="revealText('Pronunciation & extra words','child → children; man → men; woman → women.\n\ninfant = baby; preschooler = before school; tween / pre-teen ≈ 9–12; adolescent overlaps with teenager; adult is a broad category; pensioner receives a pension; retiree has retired; centenarian = 100+.')">Extra words / pronunciation</button></div><p class="axisFeedback">${axisChecked?(Object.keys(axisPlaced).length<7?'Place all seven cards. Green = a suggested age fits; ↻ = try a different age.':'Green = a suggested age fits; ↻ = try a different age. Most boundaries are approximate; teenager is 13–19.'):(axisSelected===null?'Select a stage to place it.':'Selected: '+axisStages[axisSelected][0])}</p></div>`)}
const timelineId=names.indexOf('Life Stage Sorting');names[timelineId]='Stages of Life · Timeline';subs[timelineId]='';renderers[timelineId]=rTimeline;tnotes[timelineId]='Single consolidated age-sequencing activity. Cards begin shuffled and contain no age hints. Drag/drop or choose then click the numeric age line; precise numeric placement is available. Check uses the approximate Student’s Book ranges: baby 0–1, toddler 2–3, child 4–12, teenager 13–19, young adult 20–39, middle-aged 40–64, senior 65+. Only teenager has a precise name-based boundary. Retained irregular plurals and overlapping extra terms under a reveal button.';
