function renderFamily4(){stage.innerHTML=shell(`<div class="family4"><div class="family4Bank">${sh(family4Words).map(x=>`<span>${x}</span>`).join('')}</div><div class="family4Sentences"><div><b>1</b><p>If you’re ${f4Input(0)}, you aren’t married.<br>If you’re married and then you end the marriage, you’re ${f4Input(1)}.</p></div><div><b>2</b><p>An ${f4Input(2)} doesn’t have any brothers or sisters.</p></div><div><b>3</b><p>You can use the word ${f4Input(3)} to describe either a husband or wife, or the person that someone lives with.</p></div><div><b>4</b><p>${f4Input(4)} families are families in which only the father or the mother lives at home and looks after the children.</p></div><div><b>5</b><p>Your ${f4Input(5)} family is you, your parents and your brothers and sisters. Your ${f4Input(6)} family includes grandparents, cousins, etc.</p></div><div><b>6</b><p>A ${f4Input(7)} is one of two children born at the same time to the same mother.</p></div><div><b>7</b><p>A ${f4Input(8)} is a member of your family, especially one who doesn’t live with you.</p></div></div><div class="controls"><button class="action" onclick="family4Checked=true;renderFamily4()">Check</button><button class="action alt" onclick="revealText('Exercise 4 · Answers','1 single, divorced\n2 only child\n3 partner\n4 one-parent\n5 immediate, extended\n6 twin\n7 relative')">Reveal answers</button><button class="action alt" onclick="family4Values=Array(9).fill('');family4Checked=false;renderFamily4()">Reset</button><button class="action alt" onclick="enlarge('assets/family-exercise4-user.webp')">Original exercise</button><span>${family4Checked?family4Values.filter((v,i)=>norm(v)===family4Answers[i]).length+' / 9':''}</span></div></div>`)}
